{
  "passageId": "tax-incidence",
  "items": [
    {
      "id": "R1",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "조세 부담이 불공평해질 수 있다는 문제에 대해 정부가 조세 귀착을 고려하는 대응을 제시한다."
    },
    {
      "id": "R2",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "조세 부담의 귀착을 법적 납부 책임자 기준과 실질 납부자 기준으로 대비한다."
    },
    {
      "id": "R3",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "부담 전가의 가능성을 제시하여 법적 납부 책임자가 실질 부담을 모두 진다는 통념을 반박한다."
    },
    {
      "id": "R4",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "조세 귀착에 대한 포괄적인 설명을 법적 귀착과 경제적 귀착의 구분으로 더 자세히 풀어 준다."
    },
    {
      "id": "R5",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "볼펜 과세 사례가 가격 변동을 통한 조세 부담 전가라는 일반적 설명을 구체적으로 보여 준다."
    },
    {
      "id": "R6",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "공급자에게 세금이 부과된다는 사실과 법적 귀착의 정의로부터 법적 귀착이 공급자에게 발생한다는 판단이 나온다."
    },
    {
      "id": "R7",
      "type": "CAUSE",
      "otherName": "",
      "reason": "공급자가 세액만큼 가격을 높여 받으려는 행동이 새로운 균형 가격의 형성으로 이어진다."
    },
    {
      "id": "R8",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "기존 가격 700원과 새로운 가격 760원의 차이를 계산하여 공급자가 60원을 더 받는다는 결과를 도출한다."
    },
    {
      "id": "R9",
      "type": "CAUSE",
      "otherName": "",
      "reason": "가격 인상으로 공급자가 추가로 받는 60원이 실제로 공급자의 조세 부담을 일부 상쇄한다."
    },
    {
      "id": "R10",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "수요자가 기존보다 60원을 더 지불한다는 내용을 조세 부담 60원이 수요자에게 전가된 것으로 다시 표현한다."
    },
    {
      "id": "R11",
      "type": "CAUSE",
      "otherName": "",
      "reason": "조세 부담의 일부가 수요자에게 넘어가는 것이 공급자의 부담을 줄이는 실제 작용으로 제시된다."
    },
    {
      "id": "R12",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "기존 수취액 700원에서 조세 납부 후 수취액 660원을 빼면 공급자의 최종 부담 40원이 도출된다."
    },
    {
      "id": "R13",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "수요자에게 60원의 부담이 전가되었다는 내용을 수요자에게 60원의 조세가 귀착된다는 말로 다시 나타낸다."
    },
    {
      "id": "R14",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "과세 대상이 공급자인 경우와 수요자인 경우를 가격 변화와 부담 전가 방향이라는 같은 기준에서 대비한다."
    },
    {
      "id": "R15",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "수요자 과세에 따른 공급자 부담의 발생을 통해 가격 변동에 의한 부담 전가를 구체적으로 설명한다."
    },
    {
      "id": "R16",
      "type": "CAUSE",
      "otherName": "",
      "reason": "수요자 과세로 발생한 수요 감소가 새로운 균형 가격의 하락을 일으킨다."
    },
    {
      "id": "R17",
      "type": "CAUSE",
      "otherName": "",
      "reason": "균형 가격이 하락함에 따라 공급자가 실제로 받는 금액이 줄어든다."
    },
    {
      "id": "R18",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "공급자의 수취액이 과세 이전보다 감소했다는 사실이 조세 부담 일부가 공급자에게 전가되었다는 판단을 뒷받침한다."
    },
    {
      "id": "R19",
      "type": "CAUSE",
      "otherName": "",
      "reason": "조세 부담 일부가 공급자에게 넘어가기 때문에 수요자의 실질 부담이 부과된 세액보다 작아진다."
    },
    {
      "id": "R20",
      "type": "CAUSE",
      "otherName": "",
      "reason": "조세 부담의 전가가 법적 납부 책임과 실제 부담 배분 사이의 차이를 발생시킨다."
    },
    {
      "id": "R21",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "누가 조세를 더 부담하는지 질문을 던진 뒤 가격 탄력성이 이를 결정한다는 답으로 논의를 전개한다."
    },
    {
      "id": "R22",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "가격 탄력성이 큰 경우와 작은 경우를 수량의 반응 정도와 곡선의 기울기라는 동일한 기준에서 대비한다."
    },
    {
      "id": "R23",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "조세 부담이 가격 탄력성에 달려 있다는 설명을 상대적으로 비탄력적인 쪽의 부담이 더 크다는 내용으로 구체화한다."
    },
    {
      "id": "R24",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "부담 전가로 법적 귀착과 경제적 귀착이 달라진다는 설명에서 양쪽의 최종 부담 크기를 결정하는 요인으로 논의를 확장한다."
    },
    {
      "id": "R25",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "탄력성이 거래량에 영향을 준다는 설명을 탄력성이 작은 재화의 거래량 감소가 더 적다는 내용으로 자세히 풀어 준다."
    },
    {
      "id": "R26",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "탄력성에 따른 거래량 감소의 차이라는 원리를 정부의 세수 증대를 위한 과세 재화 선택에 적용한다."
    },
    {
      "id": "R27",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "정부의 조세 정책에 관한 논의를 부담의 공평성 확보에서 세수 증대를 위한 재화 선택으로 넓힌다."
    }
  ]
}

